// The mutation gaps of the first run (scratch mut/: 16 of 38 survivors): the signed WORD 8000 and the negative index of the MULS operands, the BYTE
// table value >= 80 of 1cb76 (the WORD index), the LONG borrow of 1d722, the WORD indices of 1e744 / 21a42 / 4ecec (>= 100), the WORD compare of
// 1e93e, the BYTE size of the TST.B 7d82 / 7e80(A5), the sign-extended -7ffd(A5) of 4a930, the zero result of 1e5f0, the BYTE D0 of 4ecac.
void rules_g(){
 // ---- 1e5ba: MULS.W reads the signed WORD 8000 (synthetic k 6 / 70): D2 = 500 x -8000, D3 = 400 x -8000; D1.W = ffc2 -> index -7c: both tables
 // (4419e - 7c = 44122, 4411e - 7c = 440a2) are read below their base (sign-extended index).
 {Bytes ram=base_ram("");State s=pre(0x1e5ba,0,6);check(runs_to(ram,s,0x4c2c4)&&s.d[2]==0xfd800000U&&s.d[3]==0xfe000000U,"1e5ba WORD 8000");}
 {Bytes ram=base_ram("");State s=pre(0x1e5ba,0,0xffc2);check(runs_to(ram,s,0x4c2c4)&&s.d[1]==0xff84U&&s.d[2]==0xb5e00U&&s.d[3]==0xfee61800U,"1e5ba negative index");}
 // ---- 1cb76: the 1c1c4 BYTE 90 (record BYTE 4 = 1f) doubles to the WORD index 120 (A0 + 120).
 {Bytes ram=base_ram("");put(ram,NODE+0x8c,4,REC);put(ram,REC+4,1,0x1f);put(ram,CHILD+0x120,2,3);put(ram,CHILD+0x20,2,1);put(ram,NODE+0x22,4,LTAB);put(ram,LTAB+12,4,0x77);
  put(ram,LTAB+4,4,0x66);State s=st(0x1cb76);s.a[0]=CHILD;check(runs_to(ram,s,0x49f96)&&s.a[1]==0x77U,"1cb76 BYTE 90");}
 // ---- 1d722: SUB.W 4(A1),D1 borrows inside the WORD only (D1 = 9abc0100 - 0200 -> 9abcff00).
 {Bytes ram=base_ram("");put(ram,A5+0x5392,2,0x200);State s=pre(0x1d722,0x12345678,0x9abcdef0);check(runs_to(ram,s,0x43e08)&&s.d[1]==0x9abcff00U&&s.d[0]==0x12340000U,"1d722 WORD borrow");}
 // ---- 1e744: the index 2 x BYTE 7c(A0) and 2 x (4 x BYTE 7c + WORD 76) are WORDs (7c = 80 -> 1e876: no physical byte, even when the second index
 // 2 x (200 + fe00) wraps to 0; 76 = 80 -> 1e87c).  The run stop is the call 43e34 that a BYTE index would reach.
 {Bytes ram=base_ram("");put(ram,PARENT+0x7c,1,0x80);put(ram,PARENT+0x76,2,0xfe00);State s=st(0x1e744);s.a[0]=PARENT;reject(ram,s,0x43e34,ROM_ERROR);}
 {Bytes ram=base_ram("");put(ram,PARENT+0x76,2,0x80);State s=st(0x1e744);s.a[0]=PARENT;reject(ram,s,0x43e34,ROM_ERROR);}
 // ---- 1e93e: CMPI.W #18,D7 compares the WORD (0105 >= 18 -> 1e946).
 {Bytes ram=base_ram("");State s=st(0x1e93e);s.d[7]=0x105;check(runs_to(ram,s,0x1e60a),"1e93e 0105");}
 // ---- 21a42: the index 4 x BYTE 4 is a WORD (BYTE 40 -> 219f6 + 100: no physical byte).  4ecec: 2 x BYTE (A0) is a WORD (80 -> 4e396 + 100).
 {Bytes ram=base_ram("");put(ram,NODE+0x8c,4,REC);put(ram,REC+4,1,0x40);State s=st(0x21a42);reject(ram,s,0x1cb72,ROM_ERROR);}
 {Bytes ram=base_ram("");put(ram,REC,1,0x80);State s=st(0x4ecec);s.a[0]=REC;reject(ram,s,STOP,ROM_ERROR);}
 // ---- 4a90e / 4eb72: TST.B 7d82(A5) tests the BYTE (7d83 = 1 does not select the MVS path); 4a91e: TST.B 7e80(A5) (7e81 = 1: still the d00034 path).
 {Bytes ram=base_ram("");put(ram,A5+0x7d83,1,1);put(ram,0x100004,1,0x42);State s=pre(0x4a90e,0,0);check(runs_to(ram,s,STOP)&&s.a[1]==0x100004U&&s.d[0]==0x42U,"4a90e BYTE 7d82");}
 {Bytes ram=base_ram("");put(ram,A5+0x7e81,1,1);State s=st(0x4a91e);reject(ram,s,STOP,"unsupported program bus device address");}
 {Bytes ram=base_ram("");put(ram,A5+0x7d83,1,1);State s=st(0x4eb72);check(runs_to(ram,s,0x4a974),"4eb72 BYTE 7d82");}
 // ---- 4a930: TST.B -7ffd(A5) is the sign-extended displacement (A5 = 1f8000: 1f0003 in the RAM mirror; 1f8000 + 8003 = 200003 is the bank window).
 {Bytes ram=base_ram("");put(ram,0x1f0003,1,0);put(ram,0x100004,1,0x33);State s=pre(0x4a930,1,0);s.a[5]=0x1f8000;s.a[1]=0x100004;
  check(runs_to(ram,s,STOP)&&s.d[0]==0x33U,"4a930 A5 1f8000");}
 // ---- 1e5f0: SUBI.W #10 with the result 0 is not negative (BPL taken: 1e5fc does not write WORD 3a; the node in fixed ROM is never written).
 {Bytes ram=base_ram("");put(ram,SP,2,0x1234);put(ram,SP+2,4,STOP);State s=pre(0x1e5f0,0xfff0,0);s.a[6]=0x1b000;check(runs_to(ram,s,STOP)&&s.d[0]==0x1234U,"1e5f0 result 0");}
 // ---- 4ecac: MOVE.B 5d1f(A5),D0 replaces the BYTE only (WORD 76 = 0100: D0 = 0001xx).
 {Bytes ram=base_ram("");put(ram,NODE+0x76,2,0x100);put(ram,A5+0x5d1f,1,7);put(ram,NODE+0x9a,1,7);State s=pre(0x4ecac,0x12345678,0);
  check(runs_to(ram,s,0x4ecd8)&&s.d[0]==0x12340107U,"4ecac BYTE D0");}
}
void rules(){rules_a();rules_b();rules_c();rules_d();rules_e();rules_f();rules_g();}
